package org.firstinspires.ftc.teamcode.mechanisms.shooter;

// ftc-construct: generated by the Refract suite (ftc-construct skill) against
// team-config.yaml fixture veteran-swerve-turret.yaml (season_mechanisms.shooter: flywheel).
// Adapted from refract-suite/ftc-shared-foundation/quickstart-template's FlywheelShooter.java,
// built on FTCLib's Motor in Motor.RunMode.VelocityControl (config.software_stack.opmode_style:
// ftclib_command_based).

import com.arcrobotics.ftclib.command.SubsystemBase;
import com.arcrobotics.ftclib.hardware.motors.Motor;

import com.qualcomm.robotcore.hardware.HardwareMap;

import org.firstinspires.ftc.teamcode.RobotConstants;

/**
 * Single-flywheel {@link Shooter}, direct-driven 1:1 (no external reduction) by the motor
 * named in {@link RobotConstants#SHOOTER_MOTOR_SKU}.
 *
 * ABSTENTION -- read before tuning:
 * The requested part, goBILDA SKU 5203-2402-0001 ("6000 RPM 1:1" bare/no-gearbox 5203), is
 * NOT SEEDED in ftc-hardware-lookup's catalog (references/catalogs/motors.json). Running:
 *
 *   python3 .claude/skills/ftc-hardware-lookup/scripts/motor_math.py spec 5203-2402-0001
 *
 * returns (verbatim):
 *   {
 *     "abstain": true,
 *     "reason": "'5203-2402-0001' is not in the verified catalog. I don't have a sourced spec for it.",
 *     "do_not": "Do not fill this from memory -- report the abstention and point to the manufacturer page.",
 *     "known_skus": ["2000-0025-0002", "5203-2402-0014", "5203-2402-0019", "REV-41-1291", "REV-41-1300"]
 *   }
 * (same abstention on the `ticks` and `external` subcommands for this SKU -- exit code 3.)
 *
 * The catalog's own known_gaps note is explicit that other 5203/5202 ratios, including 1:1,
 * are NOT seeded and that a ratio's existence/specs must not be interpolated from a seeded
 * sibling (per-ratio gearbox efficiency differs; encoder CPR at the output shaft differs).
 * The only seeded 5203 variants are 19.2:1 (5203-2402-0019) and 13.7:1 (5203-2402-0014),
 * neither of which is a 1:1 direct-drive part -- so there is no seeded sibling close enough to
 * borrow an encoder CPR or no-load RPM from either.
 *
 * Consequently: NO_LOAD_RPM_OUTPUT and MAX_VELOCITY_TICKS_PER_SEC below are deliberately left
 * unset (NaN) rather than filled with an invented number. Before this subsystem can run in
 * VelocityControl with a real target, a teammate must pull the actual free-speed RPM and
 * encoder CPR from the goBILDA product page for 5203-2402-0001 (or an equivalent verified
 * source), add it to ftc-hardware-lookup's motors.json catalog, and re-run motor_math.py spec
 * to get a grounded number -- do not hand-type a spec sheet value into this file directly;
 * route it through the catalog so it stays a cited, re-checkable value.
 */
public class FlywheelShooter extends SubsystemBase implements Shooter {

    // ponytail: no encoder CPR / free-speed RPM is seeded for this SKU, so max ticks/sec
    // cannot be computed yet. NaN is a loud, fail-fast placeholder -- not a guess like
    // "1500 ticks/sec" would be. Replace via catalog lookup (see class javadoc), not by hand.
    public static final double NO_LOAD_RPM_OUTPUT = Double.NaN; // TODO: fill from catalog, not memory
    public static final double MAX_VELOCITY_TICKS_PER_SEC = Double.NaN; // TODO: fill from catalog, not memory

    private Motor flywheel;
    private double targetRpm = 0.0;

    @Override
    public void init(HardwareMap hardwareMap) {
        if (Double.isNaN(MAX_VELOCITY_TICKS_PER_SEC)) {
            throw new IllegalStateException(
                "FlywheelShooter: motor spec for SKU 5203-2402-0001 is not in the catalog yet. "
                + "Seed references/catalogs/motors.json and re-run motor_math.py spec before "
                + "using this subsystem -- see the class javadoc abstention note.");
        }

        flywheel = new Motor(hardwareMap, "shooter");
        flywheel.setRunMode(Motor.RunMode.VelocityControl);
    }

    /** Command a target flywheel speed, in RPM. Pass 0 to spin down. */
    @Override
    public void setTargetVelocity(double rpm) {
        targetRpm = rpm;
        flywheel.set(rpm / flywheel.getMaxRPM());
    }

    /** Current measured flywheel speed, in RPM. */
    @Override
    public double getCurrentVelocity() {
        // encoder rate is in ticks/sec; convert to RPM via counts-per-revolution
        return flywheel.getRate() * 60.0 / flywheel.getCPR();
    }

    @Override
    public boolean atTargetVelocity() {
        return Math.abs(getCurrentVelocity() - targetRpm) <= RobotConstants.SHOOTER_VELOCITY_TOLERANCE_RPM;
    }

    @Override
    public void stop() {
        targetRpm = 0.0;
        flywheel.stopMotor();
    }
}
